export const today=(date=new Date())=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
export const learners=Object.freeze([{id:'saif',name:'Saif',language:'ar'},{id:'fadi',name:'Fadi',language:'it'}]);
const defaults=()=>({schemaVersion:1,language:'it',settings:{theme:'system',fontSize:15,transliteration:true,ipa:false,diacritics:true,articles:true,autoplay:false,sounds:true,speed:1,goal:10,newLimit:20,reviewLimit:100,strict:false,voices:{},hearts:false},languages:{},custom:[],decks:[],activity:{},xp:0,freeze:0,freezeEarned:0});
let activeId=null,warning='',value=defaults(),timer,lastSaved=null;
const profileKey=id=>`parola.progress.${id}.v1`,legacyKey='parola.progress.v1';
const memoryProfiles=new Map();
const clone=data=>JSON.parse(JSON.stringify(data));
export function migrate(data){if(!data||typeof data!=='object'||data.schemaVersion!==1)throw Error('Unsupported backup version.');const d=defaults();return {...d,...data,settings:{...d.settings,...data.settings,voices:{...data.settings?.voices}}};}
export function state(){return value;}
export function currentLearner(){return learners.find(x=>x.id===activeId)??null;}
export function storageWarning(){return warning;}
export function savedAt(){return lastSaved;}
function read(key){const text=localStorage.getItem(key);return text?validateBackup(JSON.parse(text)):null;}
// Preserve the old shared save; copy each language into its matching profile.
function migrateLegacy(profile){let old;try{old=read(legacyKey);}catch{return null;}if(!old)return null;const v=defaults(),code=profile.language;v.settings=clone(old.settings);if(old.languages[code])v.languages[code]=clone(old.languages[code]);v.custom=clone(old.custom.filter(x=>x.language===code));v.decks=clone(old.decks.filter(x=>x.language===code));const history=v.languages[code]?.history||[];for(const h of history){const day=today(new Date(h.at)),a=v.activity[day]??={xp:0,cards:0,seconds:0};a.cards++;a.xp+=h.correct?10:0;}
 if(old.language===code){v.xp=old.xp;v.activity=clone(old.activity);v.freeze=old.freeze;v.freezeEarned=old.freezeEarned||0;}else v.xp=Object.values(v.activity).reduce((n,a)=>n+a.xp,0);return v;}
export function selectLearner(id){const profile=learners.find(x=>x.id===id);if(!profile)throw Error('Choose Saif or Fadi.');flush();clearTimeout(timer);activeId=id;warning='';lastSaved=null;let loaded=null;try{try{loaded=read(profileKey(id));}catch{warning='The latest save could not be read. Restoring the recovery copy if available.';}if(!loaded){try{loaded=read(profileKey(id)+'.recovery');}catch{}if(loaded)warning='Restored the recovery copy of your saved progress.';}loaded??=migrateLegacy(profile);localStorage.setItem('parola.check','1');localStorage.removeItem('parola.check');}catch{warning='Browser storage is unavailable. Export a backup before closing this visit.';}
 value=loaded??clone(memoryProfiles.get(id)??defaults());value.learnerId=id;value.language=profile.language;lastSaved=value.savedAt||null;lang();flush();return profile;}
export function save(){clearTimeout(timer);timer=setTimeout(flush,150);}
export function flush(){clearTimeout(timer);if(!activeId)return;memoryProfiles.set(activeId,clone(value));try{const key=profileKey(activeId);value.savedAt=new Date().toISOString();const text=JSON.stringify(value);localStorage.setItem(key,text);lastSaved=value.savedAt;try{localStorage.setItem(key+'.recovery',text);}catch{warning='Progress saved, but the browser is too full for a recovery copy. Export a backup.';}}catch{warning='Storage is full or unavailable. Export your progress to keep a backup.';}}
addEventListener('pagehide',flush);
if(typeof document!=='undefined')document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')flush();});
export function lang(code=value.language){return value.languages[code]??=({cards:{},favorites:[],added:[],mistakes:[],units:{},lastUnit:0,placement:false,history:[],bestMatch:null});}
export function settings(patch){Object.assign(value.settings,patch);save();}
export function setLanguage(code){value.language=currentLearner()?.language??code;lang();save();}
export function record(id,correct,xp=10,seconds=0){const l=lang();if(!correct&&!l.mistakes.includes(id))l.mistakes.push(id);if(correct)l.mistakes=l.mistakes.filter(x=>x!==id);l.history.push({id,correct,at:Date.now()});if(l.history.length>3000)l.history=l.history.slice(-3000);value.xp+=correct?xp:0;const a=value.activity[today()]??={xp:0,cards:0,seconds:0};a.xp+=correct?xp:0;a.cards++;a.seconds+=Math.max(0,seconds);const earned=Math.floor(value.xp/500);if(earned>(value.freezeEarned||0)){value.freeze+=earned-(value.freezeEarned||0);value.freezeEarned=earned;}save();}
export function streak(){const d=new Date();if(!value.activity[today(d)])d.setDate(d.getDate()-1);let n=0;while(value.activity[today(d)]?.cards){n++;d.setDate(d.getDate()-1);}return n;}
export function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export function exportProgress(){flush();download(`parola-${activeId||'progress'}-${today()}.json`,JSON.stringify(value,null,2));}
export function validateBackup(data){const v=migrate(data);if(!['it','ar'].includes(v.language)&&!/^[-a-z]+$/.test(v.language))throw Error('Invalid language.');if(v.learnerId&&!learners.some(x=>x.id===v.learnerId))throw Error('Invalid learner.');if(!Number.isFinite(v.xp)||v.xp<0)throw Error('Invalid XP.');for(const k of ['languages','activity'])if(!v[k]||typeof v[k]!=='object'||Array.isArray(v[k]))throw Error('Invalid '+k);if(!Array.isArray(v.custom)||!Array.isArray(v.decks))throw Error('Invalid decks.');for(const l of Object.values(v.languages)){if(!l.cards||typeof l.cards!=='object'||!Array.isArray(l.favorites)||!Array.isArray(l.history))throw Error('Invalid language progress.');for(const c of Object.values(l.cards))if(!Number.isFinite(c.due)||!Number.isFinite(c.ease)||!Number.isFinite(c.interval))throw Error('Invalid review schedule.');}return v;}
export function importProgress(text){const data=validateBackup(JSON.parse(text));if(data.learnerId&&activeId&&data.learnerId!==activeId)throw Error(`This backup belongs to ${data.learnerId}. Switch learner before importing it.`);value=data;if(activeId){value.learnerId=activeId;value.language=currentLearner().language;}flush();}
export function reset(){const profile=currentLearner();value=defaults();if(profile){value.learnerId=profile.id;value.language=profile.language;}flush();}
export async function persistenceStatus(){if(!globalThis.navigator?.storage?.persisted)return null;try{return await navigator.storage.persisted();}catch{return null;}}
export async function requestPersistence(){if(!globalThis.navigator?.storage?.persist)return null;try{return await navigator.storage.persist();}catch{return null;}}
